CREATE OR REPLACE FUNCTION public.runtime_workspace_posts_visible(p_actor_id uuid, p_result jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 PERFORM bill2_actor(p_actor_id);
 -- PR6 benchmark rights
 IF p_result->>'gold_review'='true' AND NOT coalesce((SELECT p.membership_level='gold' AND bool_or(mp.allow_benchmark_monitor)
